package com.cxy.workbench;
import org.json.*;
import java.util.*;

/** Phone-size action layout; all positions and font sizes use launcher dp. */
final class MobileActionPainter {
 static List<ActionPainter.Hit> draw(CardPainter.Surface p,JSONObject data,int group,String mode,int page,String selected,float w,float h,boolean dark){
  CardPainter.Theme t=new CardPainter.Theme(dark);List<ActionPainter.Hit> hits=new ArrayList<>();p.rect(0,0,w,h,16,t.bg);p.text("行动台",14,32,20,t.ink,true);float tx=w-100;p.rect(tx,10,86,34,14,t.faint);p.rect(tx+(mode.equals("ring")?3:44),13,39,28,11,t.panel);CardPainter.icon(p,"ring",tx+14,18,18,mode.equals("ring")?CardPainter.BLUE:t.muted);CardPainter.icon(p,"list",tx+55,18,18,mode.equals("list")?CardPainter.BLUE:t.muted);hits.add(new ActionPainter.Hit(tx,7,43,42,"mode","ring"));hits.add(new ActionPainter.Hit(tx+43,7,43,42,"mode","list"));
  float tabW=(w-28)/5;for(int i=0;i<5;i++){float x=14+i*tabW;if(i==group)p.rect(x,52,tabW-3,52,11,t.blueWash);MobileDevicePainter.text(p,(w<320?new String[]{"优先","正在做","可做","条件做","日常"}[i]:ActionPainter.GROUPS[i]),x+5,70,tabW-8,Math.max(11,Math.min(12,tabW/4.4f)),i==group?CardPainter.BLUE:t.muted,i==group);p.text(data==null?"—":Integer.toString(ActionPainter.items(data,i).size()),x+5,95,20,i==group?CardPainter.BLUE:t.ink,true);hits.add(new ActionPainter.Hit(x,49,tabW-2,57,"group",Integer.toString(i)));}
  List<JSONObject> all=ActionPainter.items(data,group);boolean ring=mode.equals("ring")&&group!=4;int cap=ring?34:Math.max(1,(int)((h-149)/59));int pages=Math.max(1,(all.size()+cap-1)/cap);page=Math.max(0,Math.min(pages-1,page));List<JSONObject> visible=all.subList(Math.min(all.size(),page*cap),Math.min(all.size(),(page+1)*cap));
  if(data==null||visible.isEmpty()){p.text(data==null?"连接后显示现有事项":"暂无该分类事项",14,140,13,t.muted,false);}
  else if(!ring){float y=119;for(JSONObject item:visible){p.circle(19,y+12,3,ActionPainter.COLORS[group%5]);MobileDevicePainter.text(p,ActionPainter.title(item),30,y+16,w-59,14,t.ink,true);String secondary=group==4?item.optString("date","")+" "+item.optString("time",""):item.optString("next",item.optString("current",""));MobileDevicePainter.text(p,secondary,30,y+37,w-59,12,t.muted,false);p.line(14,y+49,w-14,y+49,.5f,t.faint);hits.add(new ActionPainter.Hit(14,y-4,w-28,56,"open",item.optString("id")));y+=59;}}
  else{
   float side=Math.min(w-52,Math.max(112,h-173)),cx=w/2,top=118,cy=top+side/2,scale=side/268f;int n=visible.size(),outer=ActionPainter.outerCount(n);int[] palette=ActionPainter.colors(n);
   for(int i=0;i<n;i++){int ringN=i<outer?0:1,index=ringN==0?i:i-outer,count=ringN==0?outer:n-outer;float radius=side/2-ringN*36*scale-17*scale,step=360f/count,start=-90+index*step;p.arc(cx,cy,radius,34*scale,start,step,ActionPainter.COLORS[palette[i]]);double a=Math.toRadians(start+step/2);String label=ActionPainter.project(visible.get(i));if(n<=20&&side>=180)p.text(label,(float)(cx+radius*Math.cos(a))-p.measure(label,11,true)/2,(float)(cy+radius*Math.sin(a))+4,11,0xff18334d,true);}
   String number=Integer.toString(data.optJSONArray("items")==null?0:data.optJSONArray("items").length());p.text(number,cx-p.measure(number,36,true)/2,cy+12,36,t.ink,true);hits.add(new ActionPainter.Hit(cx-32,cy-27,64,54,"open",""));
   int cells=(int)Math.ceil(side/12);float unit=side/cells;for(int y=0;y<cells;y++){int x=0;while(x<cells){int from=x,owner=ActionPainter.owner((x+.5)*unit,(y+.5)*unit,n,side);x++;while(x<cells&&ActionPainter.owner((x+.5)*unit,(y+.5)*unit,n,side)==owner)x++;if(owner>=0)hits.add(new ActionPainter.Hit((w-side)/2+from*unit,top+y*unit,(x-from)*unit,unit,"select",visible.get(owner).optString("id")));}}
   float y=top+side+13;JSONObject chosen=null;for(JSONObject item:visible)if(item.optString("id").equals(selected))chosen=item;if(chosen!=null&&y+18<h-32){MobileDevicePainter.text(p,ActionPainter.title(chosen),14,y+13,w-28,13,t.ink,true);hits.add(new ActionPainter.Hit(14,y-3,w-28,35,"open",chosen.optString("id")));}else if(y+18<h-32){MobileDevicePainter.text(p,"点击圆环查看事项",14,y+13,w-28,12,t.muted,false);}
  }
  String stamp="尚未同步";if(data!=null)try{stamp="同步 "+java.time.format.DateTimeFormatter.ofPattern("HH:mm:ss").withZone(java.time.ZoneId.of("Asia/Shanghai")).format(java.time.Instant.parse(data.optString("generatedAt")));}catch(Exception e){stamp="同步时间未知";}p.text(stamp,14,h-12,11,t.muted,false);p.text("↻",w-42,h-10,22,CardPainter.BLUE,false);hits.add(new ActionPainter.Hit(w-60,h-39,46,39,"refresh",""));if(pages>1){p.text("‹",w-155,h-11,20,t.ink,false);p.text((page+1)+"/"+pages,w-126,h-12,11,t.muted,false);p.text("›",w-85,h-11,20,t.ink,false);hits.add(new ActionPainter.Hit(w-165,h-39,42,39,"page",Integer.toString(Math.max(0,page-1))));hits.add(new ActionPainter.Hit(w-100,h-39,39,39,"page",Integer.toString(Math.min(pages-1,page+1))));}return hits;
 }
}
